function validate([grid]) {
  const n = grid.length;
  if (n < 1 || n > 200) return 'grid needs 1 to 200 rows.';
  for (const row of grid) {
    if (!Array.isArray(row) || row.length !== n) return 'grid must be square (n rows of n values).';
    if (!row.every(v => Number.isInteger(v) && v >= 1 && v <= 100000)) return 'Every value is an integer from 1 to 10^5.';
  }
  return null;
}

