function equalPairs(grid) {
  const n = grid.length;
  let count = 0;
  for (let r = 0; r < n; r++) {
    for (let c = 0; c < n; c++) {
      let same = true;
      for (let k = 0; k < n && same; k++) if (grid[r][k] !== grid[k][c]) same = false;
      if (same) count++;
    }
  }
  return count;
}

