function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const small = size === 'small';
  const n = small ? int(1, 5) : int(80, 100);
  const top = small ? int(1, 3) : (rand() < 0.5 ? 100000 : int(2, 5));
  const grid = Array.from({ length: n }, () => Array.from({ length: n }, () => int(1, top)));
  // A symmetric matrix makes row i equal column i.
  if (rand() < (small ? 0.5 : 0.85)) {
    for (let i = 0; i < n; i++) for (let j = 0; j < i; j++) grid[i][j] = grid[j][i];
    // Clone index from into index to (its row and its column), so the matrix stays symmetric
    // and the two equal rows each match two columns.
    for (let k = int(0, small ? 1 : 8); k > 0; k--) {
      const to = int(0, n - 1);
      const from = int(0, n - 1);
      grid[to] = grid[from].slice();
      for (let r = 0; r < n; r++) grid[r][to] = grid[r][from];
    }
    // Change a few cells; each one breaks the pairs of its row and column.
    for (let k = int(0, small ? 2 : 30); k > 0; k--) grid[int(0, n - 1)][int(0, n - 1)] = int(1, top);
  }
  return [grid];
}
